python3 -c '
import hashlib
from pathlib import Path
for name in ("take2_w2_4agents", "take3_w2_guards", "take1_w1_2agents"):
    pngs = sorted(Path("swarm/run", name, "evidence/frames").glob("frame_*.png"))
    by_sha = {}
    for p in pngs:
        by_sha.setdefault(hashlib.sha256(p.read_bytes()).hexdigest(), p.stat().st_size)
    print(name, "total_pngs=", len(pngs), "unique_shas=", len(by_sha), "unique_bytes=", sum(by_sha.values()))
'

